Author publishAuthorWithBooks(Author author, List<Book> books) {
    for (Book book : books) {
        if (book.price.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Cena musi byc dodatnia");
        }
        author.addBook(book);
    }
